namespace Smidgenomics.Unity.Bookmarks.Editor
{
	using System;
	using System.Collections.Generic;
	using System.Linq;
	using System.Runtime.Serialization;
	using System.Text.RegularExpressions;
	using Newtonsoft.Json;
	using UnityEditor;

	/// <summary>
	/// Query used to filter assets in DB
	/// Assets:https://docs.unity3d.com/ScriptReference/AssetDatabase.FindAssets.html
	/// </summary>
	[Serializable]
	[JsonObject(MemberSerialization.OptIn)]
	internal sealed class BKQuery
	{
		// Get asset guids or paths generated by query
		public IEnumerable<string> GetIncludes()
		{
			return _includesGetter.Invoke();
		}

		[OnDeserialized]
		private void OnDeserialized(StreamingContext context)
		{
			if (_folders is not { Count: > 0 })
			{
				return;
			}

			if (_filter.Contains('*'))
			{
				_includesGetter = GetFilePathsWildcard;
			}
			else if (_filter.StartsWith('^') && _filter.EndsWith('$'))
			{
				_regex = new Regex(_filter.Substring(1, _filter.Length - 2));
				_includesGetter = GetFilePathsRegex;
			}
			else
			{
				_includesGetter = GetAssetGUIDs;
			}
		}

		// search pattern
		[JsonProperty("filter")] private string _filter = string.Empty;

		// Folders to search
		[JsonProperty("folders")] private HashSet<string> _folders = new();

		private Regex _regex;

		private IEnumerable<string> GetFilePathsWildcard()
		{
			List<string> paths = new();
			foreach (var folder in _folders)
			{
				var files = BKUtils.ListFiles(folder, _filter, true);
				foreach (var file in files)
				{
					paths.Add(file.Replace(@"\", "/"));
				}
			}
			return paths;
		}

		private IEnumerable<string> GetFilePathsRegex()
		{
			List<string> paths = new();
			foreach (var folder in _folders)
			{
				// this initial filter is too broad...
				var files = BKUtils.ListFiles(folder, "*", true);

				foreach (var file in files)
				{
					var p = file.Replace(@"\", "/");
					if (_regex.IsMatch(p))
					{
						paths.Add(p);
					}
				}
			}
			return paths;
		}

		private string[] GetAssetGUIDs()
		{
			return AssetDatabase.FindAssets(_filter, _folders.ToArray());
		}
		
		private static string[] EmptyGetter() => Array.Empty<string>();

		private Func<IEnumerable<string>> _includesGetter = EmptyGetter;

	}
}